IF (SELECT COUNT(*) FROM #TaskMasterStage) <> @expectedRowCount
    THROW 51000, 'TaskMaster seed row count is invalid.', 1;

IF EXISTS
(
    SELECT [regionCode], [taskCode]
    FROM #TaskMasterStage
    GROUP BY [regionCode], [taskCode]
    HAVING COUNT(*) > 1
)
    THROW 51001, 'TaskMaster seed contains duplicate task codes.', 1;

BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE [ref].[TaskMaster]
    SET [isCurrent] = 0
    WHERE
        [regionCode] = 'US'
        AND [isCurrent] = 1
        AND [sourceSha256] <> @sourceSha256;

    MERGE [ref].[TaskMaster] WITH (HOLDLOCK) AS target
    USING #TaskMasterStage AS source
        ON target.[regionCode] = source.[regionCode]
        AND target.[taskCode] = source.[taskCode]
        AND target.[sourceSha256] = @sourceSha256
    WHEN MATCHED THEN
        UPDATE SET
            target.[description] = source.[description],
            target.[active] = source.[active],
            target.[glCipMajorAccount] = source.[glCipMajorAccount],
            target.[glCipSubAccount] = source.[glCipSubAccount],
            target.[glAssetMajorAccount] = source.[glAssetMajorAccount],
            target.[glAssetSubAccount] = source.[glAssetSubAccount],
            target.[glAccumMajorAccount] = source.[glAccumMajorAccount],
            target.[glAccumSubAccount] = source.[glAccumSubAccount],
            target.[glDeprMajorAccount] = source.[glDeprMajorAccount],
            target.[glDeprSubAccount] = source.[glDeprSubAccount],
            target.[assetCategoryMajor] = source.[assetCategoryMajor],
            target.[assetCategoryMinor] = source.[assetCategoryMinor],
            target.[propertyType] = source.[propertyType],
            target.[sourceFile] = @sourceFile,
            target.[sourceSheet] = @sourceSheet,
            target.[sourceVersion] = @sourceVersion,
            target.[isCurrent] = 1,
            target.[importedAtUtc] = SYSUTCDATETIME()
    WHEN NOT MATCHED THEN
        INSERT
        (
            [regionCode],
            [taskCode],
            [description],
            [active],
            [glCipMajorAccount],
            [glCipSubAccount],
            [glAssetMajorAccount],
            [glAssetSubAccount],
            [glAccumMajorAccount],
            [glAccumSubAccount],
            [glDeprMajorAccount],
            [glDeprSubAccount],
            [assetCategoryMajor],
            [assetCategoryMinor],
            [propertyType],
            [sourceFile],
            [sourceSheet],
            [sourceVersion],
            [sourceSha256],
            [isCurrent]
        )
        VALUES
        (
            source.[regionCode],
            source.[taskCode],
            source.[description],
            source.[active],
            source.[glCipMajorAccount],
            source.[glCipSubAccount],
            source.[glAssetMajorAccount],
            source.[glAssetSubAccount],
            source.[glAccumMajorAccount],
            source.[glAccumSubAccount],
            source.[glDeprMajorAccount],
            source.[glDeprSubAccount],
            source.[assetCategoryMajor],
            source.[assetCategoryMinor],
            source.[propertyType],
            @sourceFile,
            @sourceSheet,
            @sourceVersion,
            @sourceSha256,
            1
        );

    IF
    (
        SELECT COUNT(*)
        FROM [ref].[TaskMaster]
        WHERE
            [regionCode] = 'US'
            AND [isCurrent] = 1
            AND [active] = 1
            AND [sourceSha256] = @sourceSha256
    ) <> @expectedRowCount
        THROW 51002, 'TaskMaster current row count is invalid.', 1;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;
    THROW;
END CATCH;
